    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.rowErrors.update((m) => new Map(m).set(p.id, 'Enter a date, or leave it blank for the sheet\'s today.'));
      return;
    }
    try {
      const saved = await firstValueFrom(
